// The backup file reference (/backup-files) is generated by scripts/build-backup-file-pages.mjs
// from website/backup-files/files.json and verified.json (which scripts/verify-backup-files.py
// writes from real backups). These tests keep the data, the pages and the sitemap in step.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  FILES, VERIFIED, HUB, HUB_URL, PAGES_DIR, buildAll, fileId, pagePath, pageTitle, pageUrl,
} from './build-backup-file-pages.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const site = path.join(root, 'website/static');
const read = file => fs.readFileSync(file, 'utf8');
const decode = s => s.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const titleOf = html => decode(html.match(/<title>([^<]*)<\/title>/)[1]);
const descriptionOf = html => decode(html.match(/<meta name="description" content="([^"]*)"/)[1]);

test('every fileID is the SHA-1 of its domain and path', () => {
  // The example everyone quotes, so the hashing itself is checked too.
  assert.equal(fileId('HomeDomain', 'Library/SMS/sms.db'), '3d0d7e5fb2ce288813306e4d4636395e047a3d28');
  for (const f of FILES) {
    assert.equal(f.fileID, fileId(f.domain, f.relativePath), `${f.slug}: fileID doesn't match ${f.domain}-${f.relativePath}`);
  }
});

test('every file has what its page needs', () => {
  const slugs = new Set();
  for (const f of FILES) {
    assert.match(f.slug, /^[a-z0-9-]+$/, `${f.slug}: slugs are lowercase letters, digits and dashes`);
    assert.ok(!slugs.has(f.slug), `${f.slug} is listed twice`);
    slugs.add(f.slug);
    for (const key of ['name', 'domain', 'relativePath', 'app', 'summary', 'description']) {
      assert.ok(typeof f[key] === 'string' && f[key].trim(), `${f.slug}: ${key} is missing`);
    }
    assert.ok(['sqlite', 'plist'].includes(f.kind), `${f.slug}: kind is sqlite or plist`);
    assert.equal(typeof f.encryptedOnly, 'boolean', `${f.slug}: say whether it's only in encrypted backups`);
    if (f.encryptedOnly) assert.ok(f.encryptionNote, `${f.slug}: say why it's only in encrypted backups`);
    assert.ok(f.openextract || f.notRead, `${f.slug}: say what OpenExtract does with it, or that it doesn't read it yet`);
    if (f.openextract) {
      assert.ok(f.openextract.screens?.length, `${f.slug}: which screen reads it?`);
      assert.match(f.openextract.guide, /^\/use-cases\/[a-z0-9-]+$/, `${f.slug}: the guide is a /use-cases/ page`);
      assert.ok(fs.existsSync(path.join(site, `${f.openextract.guide}.html`)), `${f.slug}: ${f.openextract.guide} doesn't exist`);
    }
    const texts = [f.summary, ...f.about, f.encryptionNote ?? '', f.notRead ?? '', f.openextract?.note ?? '',
      ...Object.values(f.columnNotes ?? {}), ...Object.values(f.keyNotes ?? {}), ...(f.companions ?? []).map(c => c.note)];
    for (const t of texts) {
      assert.equal((t.match(/`/g) ?? []).length % 2, 0, `${f.slug}: unmatched \` in "${t}"`);
      for (const [, href] of t.matchAll(/\]\(([^)]+)\)/g)) {
        if (href.startsWith('/backup-files/')) {
          assert.ok(FILES.some(o => `/backup-files/${o.slug}` === href), `${f.slug}: ${href} isn't a file page`);
        } else if (href.startsWith('/')) {
          assert.ok(fs.existsSync(path.join(site, `${href}.html`)), `${f.slug}: ${href} doesn't exist`);
        }
      }
    }
  }
});

test('every file was seen in a real backup, and the check kept only names', () => {
  assert.deepEqual(Object.keys(VERIFIED.files).sort(), FILES.map(f => f.slug).sort(),
    'verified.json is out of date: run `python scripts/verify-backup-files.py`');
  const ios = new Set(VERIFIED.backups.map(b => b.ios));
  const name = /^[A-Za-z0-9_]+$/;
  for (const f of FILES) {
    const v = VERIFIED.files[f.slug];
    assert.ok(v.seenIn.length, `${f.slug} wasn't found in any backup's Manifest.db: drop it`);
    for (const ver of [...v.seenIn, ...v.notSeenIn]) assert.ok(ios.has(ver), `${f.slug}: iOS ${ver} isn't one of the backups`);
    // Structure only: table, column and key names, never values.
    for (const [ver, tables] of Object.entries(v.tables)) {
      assert.ok(v.seenIn.includes(ver));
      for (const t of tables) assert.match(t, name, `${f.slug}: "${t}" doesn't look like a table name`);
    }
    for (const cols of Object.values(v.columns ?? {})) {
      for (const [table, names] of Object.entries(cols)) {
        for (const c of names) assert.ok(f.keyColumns[table]?.includes(c), `${f.slug}: ${table}.${c} isn't a key column`);
      }
    }
    for (const keys of Object.values(v.keys ?? {})) {
      for (const k of keys) assert.ok(f.keyNames?.includes(k), `${f.slug}: ${k} isn't a key name`);
    }
    if (f.kind === 'sqlite') assert.ok(Object.keys(v.tables).length, `${f.slug}: no backup's copy was read`);
  }
});

test('the pages are up to date', () => {
  for (const [file, content] of buildAll()) {
    assert.ok(fs.existsSync(file), `${path.relative(root, file)} is missing: run \`node scripts/build-backup-file-pages.mjs\``);
    // A Windows checkout can have CRLF line endings, which mustn't count as out of date.
    assert.ok(read(file).replace(/\r\n/g, '\n') === content.replace(/\r\n/g, '\n'),
      `${path.relative(root, file)} is out of date: run \`node scripts/build-backup-file-pages.mjs\``);
  }
  const expected = FILES.map(f => `${f.slug}.html`).sort();
  assert.deepEqual(fs.readdirSync(PAGES_DIR).sort(), expected, 'website/static/backup-files has a page that isn\'t in files.json');
});

test('titles and descriptions fit in search results', () => {
  for (const f of FILES) {
    const html = read(pagePath(f));
    const title = titleOf(html);
    assert.equal(title, pageTitle(f));
    assert.ok(title.length <= 60, `${f.slug}: title is ${title.length} characters: ${title}`);
    if (`${f.fileID} is ${f.name}`.length <= 60) assert.ok(title.includes(f.fileID), `${f.slug}: the full hash fits in the title`);
    const description = descriptionOf(html);
    assert.ok(description.length <= 155, `${f.slug}: description is ${description.length} characters`);
    assert.ok(description.includes(f.fileID), `${f.slug}: the description should name the hash`);
    assert.match(html, new RegExp(`<h1><span class="ref-hash">${f.fileID}</span>`), `${f.slug}: the heading has the hash`);
  }
  const hub = read(HUB);
  assert.ok(titleOf(hub).length <= 60, `hub title is ${titleOf(hub).length} characters`);
  assert.ok(descriptionOf(hub).length <= 155, `hub description is ${descriptionOf(hub).length} characters`);
});

test('search engines and readers can find every page', () => {
  const sitemap = read(path.join(site, 'sitemap.xml'));
  const hub = read(HUB);
  for (const url of [HUB_URL, ...FILES.map(pageUrl)]) {
    assert.match(sitemap, new RegExp(`<url><loc>${url}</loc><lastmod>\\d{4}-\\d{2}-\\d{2}</lastmod></url>`), `add ${url} to website/static/sitemap.xml`);
  }
  assert.ok(hub.includes(`<link rel="canonical" href="${HUB_URL}" />`));
  for (const f of FILES) {
    assert.ok(read(pagePath(f)).includes(`<link rel="canonical" href="${pageUrl(f)}" />`), `${f.slug}: canonical`);
    assert.ok(hub.includes(`href="/backup-files/${f.slug}"`), `the hub doesn't link ${f.slug}`);
  }
  for (const page of ['guides.html', 'use-cases/where-are-iphone-backups-stored.html', 'blog/what-is-in-an-iphone-backup.html']) {
    assert.ok(read(path.join(site, page)).includes('href="/backup-files"'), `${page} should link the hub`);
  }
  assert.ok(read(path.join(site, 'llms.txt')).includes(`(${HUB_URL})`), 'llms.txt should list the hub');
});

test('structured data parses, with breadcrumbs on every page', () => {
  for (const f of FILES) {
    const blocks = [...read(pagePath(f)).matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map(m => JSON.parse(m[1]));
    assert.equal(blocks[0]['@type'], 'TechArticle');
    assert.equal(blocks[0].url, pageUrl(f));
    const crumbs = blocks.find(b => b['@type'] === 'BreadcrumbList');
    assert.deepEqual(crumbs.itemListElement.map(i => i.item), ['https://www.openextract.app/', HUB_URL, pageUrl(f)]);
  }
  const hubBlocks = [...read(HUB).matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map(m => JSON.parse(m[1]));
  assert.deepEqual(hubBlocks.map(b => b['@type']), ['TechArticle', 'BreadcrumbList', 'ItemList']);
  assert.equal(hubBlocks[2].itemListElement.length, FILES.length);
});
